import { Group, Mesh, PlaneGeometry, DirectionalLight, Color, Texture, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, vec3, mix, smoothstep, clamp } from 'three/tsl';
import { gsap } from 'gsap';

function hexToRgbA(hex) {
  const h = String(hex).replace('#', '');
  const r = parseInt(h.substring(0, 2), 16) / 255;
  const g = parseInt(h.substring(2, 4), 16) / 255;
  const b = parseInt(h.substring(4, 6), 16) / 255;
  const a = h.length > 6 ? parseInt(h.substring(6, 8), 16) / 255 : 1;
  return { r, g, b, a };
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = config.colors ?? visualSpec.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0.45, hex: '#0b0b1000' },
      { at: 1.0, hex: '#0b0b10eb' },
    ],
  };
  const typography = config.typography ?? visualSpec.typography ?? {
    kicker: { fontSize: 9, letterSpacing: 0.12 },
    headline: { fontSize: 34, letterSpacing: -0.01 },
    body: { fontSize: 13, letterSpacing: 0 },
    caption: { fontSize: 9, letterSpacing: 0.12 },
  };
  const items = config.textContent ?? visualSpec.textContent ?? [];
  const findText = (role) => items.find((it) => it.role === role)?.text ?? '';

  const root = new Group();
  root.userData.handlers = {};

  const primitiveHandles = [];
  const timelines = [];
  const disposables = [];

  // ---------- STAGE BACKDROP (7x6 at z=-2.5, vertical gradient bg -> surface) ----------
  {
    const bgC = new Color(colors.background);
    const surfC = new Color(colors.surface);
    const bgVec = vec3(bgC.r, bgC.g, bgC.b);
    const surfVec = vec3(surfC.r, surfC.g, surfC.b);
    const geo = new PlaneGeometry(7, 6, 1, 1);
    const mat = new MeshBasicNodeMaterial();
    mat.colorNode = mix(surfVec, bgVec, smoothstep(0.0, 1.0, uv().y));
    const backdrop = new Mesh(geo, mat);
    backdrop.position.set(0, -0.25, -2.5);
    root.add(backdrop);
    disposables.push(() => { geo.dispose(); mat.dispose(); });
  }

  // ---------- PHOTO PLATE (parallax-plane, 4.0w x 2.5h, tessellated) ----------
  const layerGroup = new Group();
  layerGroup.position.set(0, 0.35, 0);
  root.add(layerGroup);

  const PLATE_W = 4.0;
  const PLATE_H = 2.5;
  const DISPLACE_AMP = 0.18;

  const placeholderTex = new Texture();
  const placeholderDepth = new Texture();

  const colorTexNode = texture(placeholderTex, uv());
  const depthTexNode = texture(placeholderDepth, uv());

  const liftC = new Color('#0d0d12');
  const shoulderC = new Color(colors.paper);
  const liftVec = vec3(liftC.r, liftC.g, liftC.b);
  const shoulderVec = vec3(shoulderC.r, shoulderC.g, shoulderC.b);

  // desaturate -8% preserving red channel, +12% midtone contrast, lift/shoulder remap
  const lum = colorTexNode.r.mul(0.299).add(colorTexNode.g.mul(0.587)).add(colorTexNode.b.mul(0.114));
  const desatG = mix(colorTexNode.g, lum, 0.08);
  const desatB = mix(colorTexNode.b, lum, 0.08);
  const desaturated = vec3(colorTexNode.r, desatG, desatB);
  const contrasted = clamp(desaturated.sub(0.5).mul(1.12).add(0.5), 0.0, 1.0);
  const graded = mix(liftVec, shoulderVec, contrasted);

  const plateMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.1, transparent: true });
  plateMat.colorNode = graded;
  plateMat.positionNode = positionLocal.add(normalLocal.mul(depthTexNode.r.mul(DISPLACE_AMP)));

  const plateOpacityCtrl = { value: 0 };
  plateMat.opacityNode = texture(placeholderTex, uv()).a.mul(0).add(plateOpacityCtrl.value);
  // opacity driven imperatively below via needsUpdate since TSL doesn't read plain JS values reactively
  const applyPlateOpacity = () => {
    plateMat.opacity = plateOpacityCtrl.value;
    plateMat.opacityNode = null;
    plateMat.transparent = true;
    plateMat.needsUpdate = true;
  };
  applyPlateOpacity();

  const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H, 64, 64);
  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.set(0, 0, 0);
  layerGroup.add(plateMesh);
  disposables.push(() => { plateGeo.dispose(); plateMat.dispose(); });

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorTexNode.value = tex;
    plateMat.needsUpdate = true;
  }).catch(() => {});

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexNode.value = tex;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // rim/key light along silhouette (node-local, within cap)
  const rimLight = new DirectionalLight(0xffffff, 0.7);
  rimLight.position.set(-1.2, 0.6, 1.5);
  layerGroup.add(rimLight);
  disposables.push(() => layerGroup.remove(rimLight));

  // subtle accent-tinted back light
  const accentColorObj = new Color(colors.accent);
  const backLight = new DirectionalLight(accentColorObj, 0.3);
  backLight.position.set(1.5, -0.5, -1.0);
  layerGroup.add(backLight);
  disposables.push(() => layerGroup.remove(backLight));

  // ---------- BOTTOM SCRIM GRADIENT ----------
  {
    const stops = (colors.gradientStops && colors.gradientStops.length >= 2)
      ? colors.gradientStops
      : [{ at: 0.45, hex: '#0b0b1000' }, { at: 1.0, hex: '#0b0b10eb' }];
    const s0 = hexToRgbA(stops[0].hex);
    const s1 = hexToRgbA(stops[stops.length - 1].hex);
    const scrimColor = vec3(s1.r, s1.g, s1.b);
    const geo = new PlaneGeometry(PLATE_W, PLATE_H, 1, 1);
    const mat = new MeshBasicNodeMaterial({ transparent: true });
    const t = uv().y.oneMinus();
    const factor = smoothstep(stops[0].at, stops[stops.length - 1].at, t);
    mat.colorNode = scrimColor;
    mat.opacityNode = mix(s0.a, s1.a, factor);
    const scrim = new Mesh(geo, mat);
    scrim.position.set(0, 0, 0.02);
    layerGroup.add(scrim);
    disposables.push(() => { geo.dispose(); mat.dispose(); });
  }

  // ---------- CAPTION BLOCK (bottom-left, 0.5 padding, 0.25 baseline rhythm) ----------
  const captionGroup = new Group();
  const anchorX = -PLATE_W / 2 + 0.5;
  const anchorY = -PLATE_H / 2 + 0.5;
  captionGroup.position.set(anchorX, anchorY, 0.03);

  let cursorY = 0;
  const bodyText = ctx.fontAtlas.createText(findText('body') || 'Every case begins as a single billet of 904L steel.', {
    fontSize: typography.body?.fontSize ?? 13,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 420,
    letterSpacingPx: (typography.body?.letterSpacing ?? 0) * (typography.body?.fontSize ?? 13),
  });
  bodyText.position.set(0, cursorY, 0);
  captionGroup.add(bodyText);
  cursorY += 0.3;

  const accentC = new Color(colors.accent);
  const hairlineGeo = new PlaneGeometry(0.75, 0.02, 1, 1);
  const hairlineMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.1 });
  hairlineMat.colorNode = vec3(accentC.r, accentC.g, accentC.b);
  hairlineMat.emissiveNode = vec3(accentC.r, accentC.g, accentC.b).mul(1.8);
  const hairline = new Mesh(hairlineGeo, hairlineMat);
  hairline.position.set(0.375, cursorY + 0.11, 0);
  captionGroup.add(hairline);
  disposables.push(() => { hairlineGeo.dispose(); hairlineMat.dispose(); });
  cursorY += 0.3;

  const headlineText = ctx.fontAtlas.createText(findText('headline') || 'Time, Machined.', {
    fontSize: typography.headline?.fontSize ?? 34,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: (typography.headline?.letterSpacing ?? 0) * (typography.headline?.fontSize ?? 34),
  });
  headlineText.position.set(0, cursorY, 0);
  captionGroup.add(headlineText);
  cursorY += 0.42;

  const kickerText = ctx.fontAtlas.createText(findText('kicker') || 'NOVA ATELIER / GENEVA', {
    fontSize: typography.kicker?.fontSize ?? 9,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: (typography.kicker?.letterSpacing ?? 0.12) * (typography.kicker?.fontSize ?? 9),
  });
  kickerText.position.set(0, cursorY, 0);
  captionGroup.add(kickerText);

  layerGroup.add(captionGroup);

  // top-right small caption tag
  const captionTag = ctx.fontAtlas.createText(findText('caption') || 'CALIBRE NA-01 / 72 HOUR RESERVE', {
    fontSize: typography.caption?.fontSize ?? 9,
    color: colors.paper,
    align: 'right',
    letterSpacingPx: (typography.caption?.letterSpacing ?? 0.12) * (typography.caption?.fontSize ?? 9),
  });
  captionTag.position.set(PLATE_W / 2 - 0.35, PLATE_H / 2 - 0.35, 0.03);
  layerGroup.add(captionTag);

  // ---------- ENTRANCE MOTION ----------
  const plateTl = gsap.timeline();
  plateTl.to(plateOpacityCtrl, {
    value: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => { plateMat.opacity = plateOpacityCtrl.value; },
  });
  timelines.push(plateTl);

  captionGroup.position.y -= 0.4;
  const captionTl = gsap.timeline({ delay: 0.12 });
  captionTl.to(captionGroup.position, {
    y: anchorY,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(captionTl);

  // ---------- CINEMATIC PRIMITIVES ----------
  for (const prim of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives[prim.name];
    if (typeof handler === 'function') {
      const handle = handler(layerGroup, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle?.timeline?.kill?.();
      handle?.cleanup?.();
    }
    for (const dispose of disposables) {
      try { dispose(); } catch (e) { /* noop */ }
    }
    placeholderTex.dispose();
    placeholderDepth.dispose();
    if (colorTexNode.value && colorTexNode.value !== placeholderTex) colorTexNode.value.dispose?.();
    if (depthTexNode.value && depthTexNode.value !== placeholderDepth) depthTexNode.value.dispose?.();
  };

  return root;
}
